<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Carbon ContentSwitcher Contrast Demo</title>
  <!-- Carbon CSS -->
  <link rel="stylesheet" href="https://unpkg.com/carbon-components/css/carbon-components.min.css" />
</head>
<body>
  <div id="root" style="padding: 2rem; background: #ffffff;"></div>
  <!-- React and ReactDOM -->
  <script src="https://unpkg.com/react/umd/react.development.js"></script>
  <script src="https://unpkg.com/react-dom/umd/react-dom.development.js"></script>
  <!-- Carbon React -->
  <script src="https://unpkg.com/carbon-components-react/umd/carbon-components-react.min.js"></script>
  <script>
    const { ContentSwitcher, Switch } = CarbonComponentsReact;
    function App() {
      const handleChange = ({ index, name, text }) => console.log('Switched to:', index, name, text);
      return (
        React.createElement('div', { style: { maxWidth: '400px' } },
          React.createElement(ContentSwitcher, { onChange: handleChange },
            React.createElement(Switch, { name: 'all', text: 'All' }),
            React.createElement(Switch, { name: 'read', text: 'Read' })
          )
        )
      );
    }
    ReactDOM.render(React.createElement(App), document.getElementById('root'));
  </script>
</body>
